// applyPeriodFilter computes time window based on period flag
func applyPeriodFilter(period PeriodFilter) (startTime, endTime time.Time) {
    now := time.Now()
    switch period {
    case PeriodWeek:
        // Last 7 days: now.Add(-7*24*time.Hour) to now
        startTime = now.Add(-7 * 24 * time.Hour)
    case PeriodMonth:
        // Last 30 days
        startTime = now.Add(-30 * 24 * time.Hour)
    case PeriodYear:
        // Last 365 days
        startTime = now.Add(-365 * 24 * time.Hour)
    }
    endTime = now
    return
}

// filterSessionsByTime filters sessions within time window
func filterSessionsByTime(sessions []strategy.Session, start, end time.Time) []strategy.Session {
    var filtered []strategy.Session
    for _, s := range sessions {
        if s.StartTime.After(start) && s.StartTime.Before(end) {
            filtered = append(filtered, s)
        }
    }
    return filtered
}
