// extractRepoName gets repository name from git remote origin URL
// Reuses git.Repository operations from explain.go patterns
func extractRepoName(repo *git.Repository) string {
    // Try remote "origin" first
    remote, err := repo.Remote("origin")
    if err != nil {
        return "unknown"
    }

    // Parse URL: git@github.com:entireio/cli.git -> "entireio/cli"
    //            https://github.com/entireio/cli.git -> "entireio/cli"
    urls := remote.Config().URLs
    if len(urls) == 0 {
        return "unknown"
    }

    url := urls[0]
    // Strip .git suffix
    url = strings.TrimSuffix(url, ".git")
    // Extract path component
    parts := strings.Split(url, "/")
    if len(parts) >= 2 {
        return parts[len(parts)-2] + "/" + parts[len(parts)-1]
    }
    return "unknown"
}

