// filterSessionsByAgent filters sessions by agent type
func filterSessionsByAgent(sessions []strategy.Session, store *checkpoint.GitStore, targetAgent agent.AgentType) ([]strategy.Session, error) {
    var filtered []strategy.Session
    for _, s := range sessions {
        // Check first checkpoint's agent field
        if len(s.Checkpoints) == 0 {
            continue
        }

        // Load checkpoint metadata to get agent type
        summary, err := store.ReadCommitted(context.Background(), s.Checkpoints[0].CheckpointID)
        if err != nil || summary == nil {
            continue
        }

        content, err := store.ReadLatestSessionContent(context.Background(), s.Checkpoints[0].CheckpointID)
        if err != nil || content == nil {
            continue
        }

        if content.Metadata.Agent == targetAgent {
            filtered = append(filtered, s)
        }
    }
    return filtered, nil
}
