func filterSessionsByTime(sessions []strategy.Session, start, end time.Time) []strategy.Session {
    var filtered []strategy.Session
    for _, s := range sessions {
        if s.StartTime.After(start) && s.StartTime.Before(end) {
            filtered = append(filtered, s)
        }
    }
    return filtered
