```go
// formatInsightsTerminal renders report as formatted terminal output
// Uses tabwriter for column alignment (pattern from explain.go's formatBranchCheckpoints)
func formatInsightsTerminal(report *InsightsReport) string {
    var sb strings.Builder

    // Header
    fmt.Fprintf(&sb, "Repository: %s\n", report.RepoName)
    fmt.Fprintf(&sb, "Period: %s (%s to %s)\n\n",
        report.Query.Period,
        report.Query.StartTime.Format("2006-01-02"),
        report.Query.EndTime.Format("2006-01-02"))

    // Aggregate Metrics Section
    sb.WriteString("## Overview\n\n")
    fmt.Fprintf(&sb, "  Sessions:           %d\n", report.TotalSessions)
    fmt.Fprintf(&sb, "  Total Time:         %s\n", formatDuration(report.TotalTimeSeconds))
    fmt.Fprintf(&sb, "  Tokens:             %s\n", formatNumber(report.TotalTokens))
    fmt.Fprintf(&sb, "  Estimated Cost:     $%.2f\n", report.EstimatedCostUSD)
    fmt.Fprintf(&sb, "  Avg Session:        %s\n", formatDuration(report.AvgSessionSeconds))
    fmt.Fprintf(&sb, "  Files Modified:     %d\n", report.FilesModified)
    fmt.Fprintf(&sb, "  Commits:            %d\n\n", report.CommitsLinked)

    // Agent Breakdown Table
    sb.WriteString("## Agent Breakdown\n\n")
    for _, stat := range report.AgentStats {
        fmt.Fprintf(&sb, "  %-15s  %3d sessions  (%5.1f%%)\n",
            stat.Agent, stat.Sessions, stat.Percentage)
    }
    sb.WriteString("\n")

    // Daily Activity (last 7 days)
    sb.WriteString("## Daily Activity\n\n")
    for _, day := range report.DailyActivity {
        fmt.Fprintf(&sb, "  %s  %2d sessions  %.1f hours\n",
            day.Date.Format("2006-01-02"), day.Sessions, day.Hours)
    }
    sb.WriteString("\n")

    // Top Tools
    sb.WriteString("## Top Tools\n\n")
    for i, tool := range report.TopTools {
        fmt.Fprintf(&sb, "  %d. %-20s  %4d uses\n",
            i+1, tool.ToolName, tool.Count)
    }
    sb.WriteString("\n")

    // Recent Sessions
    sb.WriteString("## Recent Sessions\n\n")
    for _, s := range report.RecentSessions {
        fmt.Fprintf(&sb, "  [%s]  %s  %s  %d checkpoints\n",
            s.SessionID[:12],
            s.StartTime.Format("2006-01-02 15:04"),
            formatDuration(int64(s.Duration.Seconds())),
            s.Checkpoints)
        if s.Description != "" {
            fmt.Fprintf(&sb, "    %s\n", s.Description)
        }
    }

    return sb.String()
}

// Helper formatters
func formatDuration(seconds int64) string {
    d := time.Duration(seconds) * time.Second
    h := int(d.Hours())
    m := int(d.Minutes()) % 60
    if h > 0 {
        return fmt.Sprintf("%dh %dm", h, m)
    }
    return fmt.Sprintf("%dm", m)
}

func formatNumber(n int64) string {
    // Add thousands separators: 1234567 -> "1,234,567"
    s := fmt.Sprintf("%d", n)
    var result strings.Builder
    for i, c := range s {
        if i > 0 && (len(s)-i)%3 == 0 {
            result.WriteRune(',')
        }
        result.WriteRune(c)
    }
    return result.String()
}
```

