// formatInsightsMarkdown renders report as Markdown document
func formatInsightsMarkdown(report *InsightsReport) ([]byte, error) {
    var sb strings.Builder

    // Front matter
    fmt.Fprintf(&sb, "# Session Insights: %s\n\n", report.RepoName)
    fmt.Fprintf(&sb, "**Period:** %s (%s to %s)\n\n",
        report.Query.Period,
        report.Query.StartTime.Format("2006-01-02"),
        report.Query.EndTime.Format("2006-01-02"))

    // Overview section
    sb.WriteString("## Overview\n\n")
    sb.WriteString("| Metric | Value |\n")
    sb.WriteString("|--------|-------|\n")
    fmt.Fprintf(&sb, "| Sessions | %d |\n", report.TotalSessions)
    fmt.Fprintf(&sb, "| Total Time | %s |\n", formatDuration(report.TotalTimeSeconds))
    // ... (similar to terminal formatter but in table format)

    // Agent breakdown as chart
    sb.WriteString("\n## Agent Breakdown\n\n")
    sb.WriteString("```\n")
    for _, stat := range report.AgentStats {
        bar := strings.Repeat("█", int(stat.Percentage/2))
        fmt.Fprintf(&sb, "%-15s %s %.1f%%\n", stat.Agent, bar, stat.Percentage)
    }
    sb.WriteString("```\n\n")

