func newInsightsCmd() *cobra.Command {
    var periodFlag string
    var repoFlag string
    var agentFlag string
    var jsonFlag bool
    var exportFlag bool
    var formatFlag string
    var outputFile string

    cmd := &cobra.Command{
        Use:   "insights",
        Short: "Show session analytics and metrics",
        Long: `Insights aggregates metrics across sessions:
  - Total time, tokens, costs
  - Agent breakdown
  - Daily/weekly/monthly activity
  - Top tools and repositories
  - Recent sessions

Examples:
  entire insights                          # Last week's activity
  entire insights --period month           # Last 30 days
  entire insights --agent claude-code      # Claude Code sessions only
  entire insights --export --format json   # Export as JSON`,
        RunE: func(cmd *cobra.Command, _ []string) error {
            if checkDisabledGuard(cmd.OutOrStdout()) {
                return nil
            }

            // Validate flags
            if exportFlag && (formatFlag != "" || outputFile != "") && !exportFlag {
                return errors.New("--format and --output require --export flag")
            }
            if jsonFlag && exportFlag {
                return errors.New("--json and --export are mutually exclusive")
            }

            return runInsights(cmd.OutOrStdout(), periodFlag, repoFlag, agentFlag, 
                             jsonFlag, exportFlag, formatFlag, outputFile)
        },
    }

    cmd.Flags().StringVar(&periodFlag, "period", "week", "Time period: week, month, year")
    cmd.Flags().StringVar(&repoFlag, "repo", "", "Filter by repository name")
    cmd.Flags().StringVar(&agentFlag, "agent", "", "Filter by agent: claude-code, gemini-cli")
    cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON (shorthand for --export --format json)")
    cmd.Flags().BoolVar(&exportFlag, "export", false, "Export in structured format")
    cmd.Flags().StringVar(&formatFlag, "format", "json", "Export format: json, markdown")
    cmd.Flags().StringVarP(&outputFile, "output", "o", "", "Write to file instead of stdout")

    cmd.MarkFlagsMutuallyExclusive("json", "export")

    return cmd
}
```

### Routing Logic (in `insights.go`)
```go
func runInsights(w io.Writer, period, repo, agent string, json, export bool, format, outputFile string) error {
    // Parse period
    var periodFilter PeriodFilter
    switch period {
    case "week":
        periodFilter = PeriodWeek
    case "month":
        periodFilter = PeriodMonth
    case "year":
        periodFilter = PeriodYear
    default:
        return fmt.Errorf("invalid period: %s (must be week, month, or year)", period)
    }

    // Parse agent filter
    var agentFilter agent.AgentType
    if agent != "" {
        agentFilter = agent.AgentType(agent)
    }

    // Build query
    startTime, endTime := applyPeriodFilter(periodFilter)
    query := InsightsQuery{
        Period:      periodFilter,
        StartTime:   startTime,
        EndTime:     endTime,
        RepoFilter:  repo,
        AgentFilter: agentFilter,
    }

    // Compute analytics
    report, err := computeInsights(query)
    if err != nil {
        return fmt.Errorf("failed to compute insights: %w", err)
    }

    // Route to formatter
    if json {
        return outputJSON(w, report, outputFile)
    }
    if export {
        return outputExport(w, report, format, outputFile)
    }
    return outputTerminal(w, report)
}
```

